message:
Running command: cd /workspace/repo-vul/src-vul && cat > /tmp/test_enum.c <<'EOF'
#include <net-snmp/net-snmp-config.h>
#include <net-snmp/net-snmp-includes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    /* Mimic snmp_config_fuzzer: only register_mib_handlers */
    register_mib_handlers();

    /* Check if "enum" handler is registered under "snmp" */
    struct config_line *h = read_config_get_handlers("snmp");
    int found = 0;
    for (; h; h = h->next) {
        if (h->config_token && strcasecmp(h->config_token, "enum") == 0) {
            found = 1;
            break;
        }
    }
    printf("enum handler registered (mib_handlers only): %s\n", found ? "YES" : "NO");

    /* Now also init_snmp_enum */
    init_snmp_enum("snmp");
    h = read_config_get_handlers("snmp");
    found = 0;
    for (; h; h = h->next) {
        if (h->config_token && strcasecmp(h->config_token, "enum") == 0) {
            found = 1;
            break;
        }
    }
    printf("enum handler registered (after init_snmp_enum): %s\n", found ? "YES" : "NO");
    return 0;
}
EOF
./net-snmp-config --base-cflags 2>/dev/null | head -c 200; echo; echo "---compile---"
gcc -I include -I agent/mibgroup/agentx $(./net-snmp-config --base-cflags 2>/dev/null) /tmp/test_enum.c -o /tmp/test_enum \
    -L snmplib/.libs -lnetsnmp -Wl,-rpath,$(pwd)/snmplib/.libs 2>&1 | head -30
echo "exit: $?"

